import java.util.*;
class ParkedVehicle {final String reg,type;final int rate;ParkedVehicle(String r,String t,int rate){reg=r;type=t;this.rate=rate;}double fee(int mins){return ((mins+59)/60)*rate;}}
class MiniParking {final String[][] slots;final Map<String,ParkedVehicle> active=new LinkedHashMap<>();MiniParking(int[] caps){slots=new String[caps.length][];for(int i=0;i<caps.length;i++)slots[i]=new String[caps[i]];}String enter(String reg,String type,int rate){if(active.containsKey(reg))return "REJECT duplicate";for(int f=0;f<slots.length;f++)for(int s=0;s<slots[f].length;s++)if(slots[f][s]==null){slots[f][s]=reg;active.put(reg,new ParkedVehicle(reg,type,rate));return "PASS parked "+reg+" at "+f+":"+s;}return "REJECT full";}String exit(String reg,int mins){ParkedVehicle v=active.remove(reg);if(v==null)return "REJECT unknown";for(String[] floor:slots)for(int s=0;s<floor.length;s++)if(reg.equals(floor[s])){floor[s]=null;return "PASS exit "+reg+" fee Rs "+v.fee(mins);}return "ERROR slot missing";}}
public class Task11 {public static void main(String[] a){MiniParking p=new MiniParking(new int[]{1,1});System.out.println(p.enter("TN01AA","BIKE",10));System.out.println(p.enter("TN02BB","CAR",30));System.out.println(p.enter("TN03CC","CAR",30));System.out.println(p.enter("TN01AA","BIKE",10));System.out.println(p.exit("TN01AA",60));System.out.println(p.enter("TN03CC","CAR",30));System.out.println(p.exit("TN03CC",0));System.out.println(p.exit("UNKNOWN",15));System.out.println("Daily total for completed exits = Rs 10 (hand calculation: 1 hour x Rs 10)");}}
